// Do whatever must happen before the backup here, for example
// stop a container with a Docker or exec node. Backrest waits
// until the response is sent, then starts the backup.
// If this fails, the Catch node tells Backrest to cancel it.
node.status({ fill: "blue", shape: "dot", text: `paused for ${msg.payload.plan}` });
return msg;

msg.statusCode = 500;
msg.payload = `Couldn't prepare for the backup: ${msg.error.message}`;
return msg;

// Do whatever must happen after the backup here, for example
// start the container again. payload.error is set when the
// backup failed.
const p = msg.payload;
node.status({
    fill: p.error ? "red" : "green", shape: "dot",
    text: p.error ? `backup of ${p.plan} failed` : `backup of ${p.plan} done`
});
return msg;
